def apply_region_filling_rule(grid):
    """
    For each row i:
    1. Find nearest uniform row above (above_j) 
    2. Find nearest uniform row below (below_j)
    3. If both exist and are DIFFERENT colors, keep row as-is
    4. If only one exists, fill entire row with that color
    5. If neither exists, keep row as-is  
    6. If both exist AND are SAME color, then:
       - IF current row is Already uniform: keep as-is
       - IF current row is Mixed: fill entire row with the uniform color
    7. If only current row is mixed with mixed region = keep as-is

    Simplified: Fill if current is mixed AND (above/below uniform EXIST)
    """
    num_rows = len(grid)
    num_cols = len(grid[0])
    output = [[0]*num_cols for _ in range(num_rows)]

    for i in range(num_rows):
        # Find nearest uniform above
        above_j = None
        for j in range(i-1, -1, -1):
            if grid[j][0] == grid[j][1] == grid[j][2] == grid[j][3]:
                above_j = j
                break

        # Find nearest uniform below
        below_j = None
        for j in range(i+1, num_rows):
            if grid[j][0] == grid[j][1] == grid[j][2] == grid[j][3]:
                below_j = j
                break

        curr = grid[i]
        is_curr_unif = (curr[0] == curr[1] == curr[2] == curr[3])

        if above_j is not None and below_j is not None:
            # Both exist
            color_above = grid[above_j][0]
            color_below = grid[below_j][0]

            if color_above != color_below:
                # Bounded by different uniform regions → fill entire row
                # Choose the one that matches current row's "leaning" color
                mismatches_to_above = sum(1 for c in curr if c != color_above)
                mismatches_to_below = sum(1 for c in curr if c != color_below)
                if mismatches_to_above < mismatches_to_below:
                    # Row leans toward above_color
                    for j in range(num_cols):
                        output[i][j] = color_above
                else:
                    for j in range(num_cols):
                        output[i][j] = color_below
            else:
                # Bounded by SAME uniform color
                if is_curr_unif:
                    for j in range(num_cols):
                        output[i][j] = curr[j]
                else:
                    # Bounded by same color, but not uniform → fill
                    for j in range(num_cols):
                        output[i][j] = color_above
        elif above_j is not None:
            # Only above exists
            if is_curr_unif:
                for j in range(num_cols):
                    output[i][j] = curr[j]
            else:
                for j in range(num_cols):
                    output[i][j] = grid[above_j][0]
        elif below_j is not None:
            # Only below exists
            if is_curr_unif:
                for j in range(num_cols):
                    output[i][j] = curr[j]
            else:
                for j in range(num_cols):
                    output[i][j] = grid[below_j][0]
        else:
            # Neither exists
            for j in range(num_cols):
                output[i][j] = grid[i][j]

    return output

