def categorize_row(row_idx, grid):
    curr = grid[row_idx]
    is_curr_unif = (curr[0] == curr[1] == curr[2] == curr[3])

    # Check above: find nearest uniform row above (and its color)
    above_unif = None
    above_color = None
    for j in range(row_idx-1, -1, -1):
        if grid[j][0] == grid[j][1] == grid[j][2] == grid[j][3]:
            above_unif = j
            above_color = grid[j][0]
            break

    # Check below: find nearest uniform row below (and its color)
    below_unif = None
    below_color = None
    for j in range(row_idx+1, len(grid)):
        if grid[j][0] == grid[j][1] == grid[j][2] == grid[j][3]:
            below_unif = j
            below_color = grid[j][0]
            break

    if is_curr_unif:
        return "C_uniform"

    # Mixed row
    # Is first neighbor uniform?
    first_is_above_unif = above_unif is not None
    first_is_below_unif = below_unif is not None

    if first_is_above_unif and not first_is_below_unif:
        return f"A_after_above({above_color})"
    elif not first_is_above_unif and first_is_below_unif:
        return f"B_before_below({below_color})"
    elif first_is_above_unif and first_is_below_unif:
        if above_color == below_color:
            return f"Between_same({above_color})"
        else:
            return f"Between_diff({above_color}={below_color})"
    else:
